/**
 * Maintains the EF Core migrations of the database overlays (templates/databases/<provider>).
 * The SQL Server migrations ship with templates/default; every other provider needs its own set,
 * generated by EF Core for that provider rather than copied.
 *
 *   npm run generate-migrations -- --db postgresql --name AddTeacher   add a migration to the overlay
 *   npm run generate-migrations -- --check                             verify no provider has pending model changes
 *
 * Both modes generate a throwaway project named after the source project, so identifiers are not renamed,
 * and run the dotnet-ef version pinned in the template's tool manifest. Requires the .NET 9 SDK.
 * No database is contacted.
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { parseArgs } from 'node:util';
import { DATABASES, SUPPORTED_DATABASES, TEMPLATE_PATHS, isDatabase, type Database } from '../src/databases.js';
import { generateProject } from '../src/generate.js';
import { toPascalCase } from '../src/naming.js';
import { defaultDatabasesDir, defaultTemplateDir } from '../src/paths.js';
import { SOURCE_PROJECT_NAME } from '../src/tokens.js';

const PROJECT_NAME = 'react-dotnet-boilerplate';
const MIGRATION_NAME_PATTERN = /^[A-Z][A-Za-z0-9]*$/;

function dotnet(cwd: string, args: string[]): string {
  return execFileSync('dotnet', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
}

function efArgs(command: string[]): string[] {
  return [
    'ef',
    ...command,
    '--project',
    `${SOURCE_PROJECT_NAME}.Infrastructure`,
    '--startup-project',
    `${SOURCE_PROJECT_NAME}.Api`,
  ];
}

async function generateServer(database: Database, workDir: string): Promise<string> {
  const targetDir = path.join(workDir, database);
  await generateProject({
    templateDir: defaultTemplateDir,
    databasesDir: defaultDatabasesDir,
    targetDir,
    projectName: PROJECT_NAME,
    displayName: PROJECT_NAME,
    packageManager: 'npm',
    database,
  });
  const serverDir = path.join(targetDir, 'server');
  dotnet(serverDir, ['tool', 'restore']);
  dotnet(serverDir, ['build', `${SOURCE_PROJECT_NAME}.Api`, '-nologo', '-v', 'q']);
  return serverDir;
}

async function addMigration(database: Database, name: string, workDir: string): Promise<void> {
  const info = DATABASES[database];
  if (info.replacesPrefix !== TEMPLATE_PATHS.migrations) {
    throw new Error(`${info.name} migrations live in the source repository; add them there and run sync-template.`);
  }
  const serverDir = await generateServer(database, workDir);
  console.log(`Adding ${info.name} migration ${name}...`);
  dotnet(serverDir, [...efArgs(['migrations', 'add', name]), '--no-build']);

  const generated = path.join(path.dirname(serverDir), ...TEMPLATE_PATHS.migrations.split('/'));
  const overlayMigrations = path.join(defaultDatabasesDir, info.overlay, ...TEMPLATE_PATHS.migrations.split('/'));
  await fs.rm(overlayMigrations, { recursive: true, force: true });
  await fs.cp(generated, overlayMigrations, { recursive: true });
  console.log(`Updated ${path.relative(process.cwd(), overlayMigrations)}:`);
  (await fs.readdir(overlayMigrations)).forEach((file) => console.log(`  ${file}`));
  console.log('Review the generated migration, then run npm run generate-migrations -- --check.');
}

async function check(workDir: string): Promise<void> {
  for (const database of SUPPORTED_DATABASES) {
    const serverDir = await generateServer(database, workDir);
    const result = dotnet(serverDir, [...efArgs(['migrations', 'has-pending-model-changes']), '--no-build']);
    console.log(`${DATABASES[database].name}: ${result.trim().split(/\r?\n/).pop()}`);
  }
}

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      db: { type: 'string' },
      name: { type: 'string' },
      check: { type: 'boolean', default: false },
    },
  });
  if (toPascalCase(PROJECT_NAME) !== SOURCE_PROJECT_NAME) {
    throw new Error(`${PROJECT_NAME} no longer maps to ${SOURCE_PROJECT_NAME}; update this script.`);
  }

  const workDir = await fs.mkdtemp(path.join(os.tmpdir(), 'crda-migrations-'));
  try {
    if (values.check) {
      await check(workDir);
      return;
    }
    if (!values.db || !isDatabase(values.db)) {
      throw new Error(`Missing or unknown --db (expected one of: ${SUPPORTED_DATABASES.join(', ')}).`);
    }
    if (!values.name || !MIGRATION_NAME_PATTERN.test(values.name)) {
      throw new Error('Missing or invalid --name (PascalCase, e.g. AddTeacher).');
    }
    await addMigration(values.db, values.name, workDir);
  } finally {
    dotnet(os.tmpdir(), ['build-server', 'shutdown']);
    await fs.rm(workDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 500 }).catch(() => {
      console.warn(`Could not remove ${workDir}; delete it manually.`);
    });
  }
}

main().catch((error: unknown) => {
  const stderr = (error as { stderr?: string }).stderr;
  console.error(stderr ? `${String(error)}\n${stderr}` : error instanceof Error ? error.message : error);
  process.exitCode = 1;
});
